mem_size_t titan_uds_get_dtc_count(void)
{
    return sizeof(s_uds_dtc_database) / sizeof(s_uds_dtc_database[0]);
}

const titan_dtc_definition_t* titan_uds_get_dtc_by_index(mem_size_t idx)
{
    if (idx >= sizeof(s_uds_dtc_database) / sizeof(s_uds_dtc_database[0])) return NULL_PTR;
    return &s_uds_dtc_database[idx];
}
